#!/usr/bin/env bash
set -euo pipefail
cat > map-route-planner-v2.html <<'HTML'
<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Interactive Field Route</title><style>*{box-sizing:border-box}body{margin:0;padding:24px;background:#10141e;color:#f1f4ff;font:14px system-ui}main{max-width:880px;margin:auto}h1{font-size:clamp(25px,4vw,38px);letter-spacing:-.04em;margin:8px 0}p{color:#b1bfd5;line-height:1.6}.eyebrow{font-size:11px;letter-spacing:.15em;color:#9bbaff}.card{background:#192233;border:1px solid #ffffff20;border-radius:16px;padding:18px;margin-top:18px}button{min-height:44px;padding:8px 14px;border:1px solid #ffffff25;border-radius:8px;background:#26344b;color:#eef4ff;cursor:pointer;transition:background .15s,transform .15s}button:hover{background:#354a69}button:active{transform:scale(.96)}button[aria-pressed=true]{border-color:#a6baff;background:#334778}button:focus-visible{outline:2px solid #acd9ff;outline-offset:3px}.controls{display:flex;flex-wrap:wrap;gap:8px;margin-top:14px}.number{font-variant-numeric:tabular-nums}small{color:#b1bfd5}@media(max-width:500px){body{padding:14px}.card{padding:12px}}@media(prefers-reduced-motion:reduce){*{transition:none!important}}</style><main><div class="eyebrow">FIELD NOTES / INTERACTIVE ROUTE</div><h1>OpenEval Field Route</h1><p>Five stops through an imagined field station. Choose a landmark, step through the route, or watch the tour.</p><section class="card" aria-label="Field route map"><svg viewBox="0 0 640 180" role="img" aria-label="Route: Start to Signal bridge to Memory grove to Watchtower to Finish" style="width:100%;max-height:200px"><path d="M40 140 L180 45 L320 115 L460 35 L600 120" fill="none" stroke="#91b5df" stroke-width="4" stroke-dasharray="8 5"/><g fill="#aac9ff" stroke="#192233" stroke-width="5"><circle cx="40" cy="140" r="12"/><circle cx="180" cy="45" r="12"/><circle cx="320" cy="115" r="12"/><circle cx="460" cy="35" r="12"/><circle cx="600" cy="120" r="12"/></g></svg><div class="controls" aria-label="Choose current landmark"><button data-stop="0" aria-pressed="false">1 · Start</button><button data-stop="1" aria-pressed="false">2 · Signal bridge</button><button data-stop="2" aria-pressed="false">3 · Memory grove</button><button data-stop="3" aria-pressed="false">4 · Watchtower</button><button data-stop="4" aria-pressed="false">5 · Finish</button></div><p>Legend: numbered stops show route order; the selected button marks your position.</p></section><section class="card" aria-live="polite"><small>Current position</small><h2 id="position" class="number">1 / 5 · Start</h2><div style="height:8px;background:#ffffff15;border-radius:8px;overflow:hidden"><div id="progress" style="height:100%;width:20%;background:#95e6d0"></div></div><p id="next-action">Next: Signal bridge</p></section><div class="controls"><button id="next">Next landmark</button><button id="reset">Reset route</button><button id="tour">Watch route</button></div><p><small>Reference solution · not an agent result.</small></p></main><script>const stops=['Start','Signal bridge','Memory grove','Watchtower','Finish'];let index=0,tour=null;
function state(){return {index,label:stops[index],next:index===4?null:stops[index+1],complete:index===4};}
function render(){document.querySelectorAll('[data-stop]').forEach(b=>{const current=Number(b.dataset.stop)===index;b.setAttribute('aria-pressed',String(current));b.setAttribute('aria-current',current?'step':'false');});document.querySelector('#position').textContent=(index+1)+' / 5 · '+stops[index];document.querySelector('#next-action').textContent=index===4?'Route complete. You reached the evidence garden.':'Next: '+stops[index+1];document.querySelector('#progress').style.width=((index+1)/5*100)+'%';document.querySelector('#next').disabled=index===4;}
function select(i){if(!Number.isInteger(i)||i<0||i>=stops.length)throw new RangeError('Unknown stop');index=i;render();return state();}
function next(){return select(index+1);}function reset(){if(tour){clearInterval(tour);tour=null;}document.querySelector('#tour').textContent='Watch route';return select(0);}
window.evaluationDemo={select,next,reset,getState:state};
document.querySelectorAll('[data-stop]').forEach(b=>b.onclick=()=>select(Number(b.dataset.stop)));document.querySelector('#next').onclick=next;document.querySelector('#reset').onclick=reset;document.querySelector('#tour').onclick=()=>{if(tour){clearInterval(tour);tour=null;document.querySelector('#tour').textContent='Watch route';return;}reset();document.querySelector('#tour').textContent='Stop tour';tour=setInterval(()=>{next();if(index===4){clearInterval(tour);tour=null;document.querySelector('#tour').textContent='Watch route';}},1100);};render();</script></html>
HTML
